"""Caches standard PGD deltas per (model, seed, image index), so every defense variant
is evaluated on the same attacked images without regenerating them.
Never cache adaptive attacks: those depend on the defense.

Each file stores the attack parameters it was generated with ({"meta": ..., "deltas": ...}).
Loading with different parameters raises instead of silently reusing stale attacks."""
import os

import torch

from . import RESULTS_DIR

CACHE_DIR = os.path.join(RESULTS_DIR, "cache")

# Files written before metadata existed (2026-10-26, commits 101854d-ad0c330) were all
# generated by attacks.pgd with these defaults; they are accepted only for these values.
LEGACY_PARAMS = {"eps": 4.0 / 255.0, "step": 1.0 / 255.0, "steps": 50}


def _same(a: dict, b: dict) -> bool:
    return a.keys() == b.keys() and all(abs(float(a[k]) - float(b[k])) < 1e-9 for k in a)


class PGDCache:
    def __init__(self, model_tag: str, seed: int, params: dict):
        os.makedirs(CACHE_DIR, exist_ok=True)
        self.path = os.path.join(CACHE_DIR, f"pgd50_{model_tag}_s{seed}.pt")
        self.params = dict(params)
        self.store = {}
        if os.path.exists(self.path):
            raw = torch.load(self.path)
            if "meta" in raw:
                stored, self.store = raw["meta"], raw["deltas"]
            else:
                stored, self.store = LEGACY_PARAMS, raw
            if not _same(stored, self.params):
                raise ValueError(f"PGD cache {self.path} was built with {stored}, requested {self.params}. "
                                 "Delete the file or use --no-cache.")
        self.dirty = False

    def has(self, indices) -> bool:
        return all(i in self.store for i in indices)

    def get(self, indices, device):
        return torch.stack([self.store[i] for i in indices]).to(device).float()

    def put(self, indices, deltas):
        for i, d in zip(indices, deltas):
            self.store[i] = d.detach().to("cpu", torch.float16)
        self.dirty = True

    def save(self):
        if self.dirty:
            torch.save({"meta": self.params, "deltas": self.store}, self.path)
            self.dirty = False
